// SigSnap-Policy - retention pruning demo
var snaps = [];
for (var i = 0; i < 30; i++) snaps.push({ day: i, size: 100 });
function prune(list, keepDaily, keepWeekly) {
  return list.filter(function(s, i) { return i >= list.length - keepDaily || (s.day % 7 === 0 && i >= list.length - keepWeekly * 7); });
}
var kept = prune(snaps, 7, 4);
console.log("System: SigSnap | Policy: declarative tiers");
console.log("Before: " + snaps.length + " snapshots, after prune: " + kept.length);
console.log("Retention: tiered -> ENFORCED");

